const products=[
 {id:1,name:'Amaris',type:'Атлас · 42–46',price:68400,color:'milk',image:'assets/dress-1.png',description:'Архитектурное платье из плотного сатина: акцентный корсет, открытая линия плеч и эффектный шлейф с разрезом.'},
 {id:2,name:'Elodie',type:'Атлас и кружево · 40–44',price:52900,color:'ivory',image:'assets/dress-2.png',description:'Короткое свадебное платье для смелого камерного праздника. Атласный лиф, кружевные рукава и воздушная юбка.'},
 {id:3,name:'Aurelia',type:'Фатин · 42–48',price:74800,color:'white',image:'assets/dress-3.png',description:'Лёгкое сияющее платье А-силуэта с корсетным лифом и невесомыми спущенными рукавами.'},
 {id:4,name:'Celeste',type:'Кружево · 40–46',price:89600,color:'champagne',image:'assets/dress-4.png',description:'Приталенная модель с сияющим кружевом, выразительным корсетом и длинным шлейфом.'},
 {id:5,name:'Genevieve',type:'Микадо · 42–48',price:82200,color:'ivory',image:'assets/dress-5.png',description:'Торжественное платье с объёмной юбкой, корсетом и мягкими рукавами-буфами.'},
 {id:6,name:'Seraphine',type:'Бисер · 42–46',price:94500,color:'white',image:'assets/dress-6.png',description:'Сияющая приталенная модель, расшитая бисером, с тонкими бретелями и длинной фатой.'}
];
let state={min:35000,max:95000,color:'all',size:null,cart:[]};
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s),rub=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽';
function visible(){return products.filter(p=>p.price>=state.min&&p.price<=state.max&&(state.color==='all'||p.color===state.color)&&(!state.size||p.type.includes(state.size)))}
function renderProducts(){const grid=$('#products');grid.innerHTML='';const items=visible();$('.result-count span').textContent=items.length;items.forEach(p=>{const node=$('#product-template').content.cloneNode(true),img=node.querySelector('img'),open=()=>openDetail(p);img.src=p.image;img.alt=`Свадебное платье ${p.name}`;node.querySelector('.product-image').onclick=open;node.querySelector('.product-title').onclick=open;node.querySelector('h3').textContent=p.name;node.querySelector('p').textContent=p.type;node.querySelector('strong').textContent=rub(p.price);grid.append(node)})}
function sizeList(p){const [min,max]=p.type.split('·')[1].split('–').map(Number);return Array.from({length:(max-min)/2+1},(_,i)=>min+i*2)}
function cartEntry(id){return state.cart.find(x=>x.id===id)}
function showToast(message){const toast=$('.toast-message');toast.textContent=message;toast.classList.add('visible');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>toast.classList.remove('visible'),4200)}
function openDetail(p){const existing=cartEntry(p.id),sizes=sizeList(p);$('.detail .sheet-top h2').textContent=p.name;$('.detail-content').innerHTML=`<img class="detail-photo" src="${p.image}" alt="Свадебное платье ${p.name}"><h3 class="detail-name">${p.name}</h3><p class="detail-price">${rub(p.price)}</p><p class="detail-description">${p.description}</p><div class="detail-size-picker"><span>Выберите размер</span><div class="detail-size-options">${sizes.map(s=>`<button type="button" class="detail-size-option ${existing?.size===s?'selected':''}" data-size="${s}" aria-pressed="${existing?.size===s?'true':'false'}">${s}</button>`).join('')}</div></div><div class="detail-meta"><div><span>Материал</span><strong>${p.type.split('·')[0].trim()}</strong></div></div><button class="add-to-cart ${existing?'in-cart':''}">${existing?'Обновить размер в корзине':'Добавить в корзину'}</button>`;let selectedSize=existing?.size||null;$$('.detail-size-option').forEach(button=>button.onclick=()=>{selectedSize=Number(button.dataset.size);$$('.detail-size-option').forEach(option=>{const selected=option===button;option.classList.toggle('selected',selected);option.setAttribute('aria-pressed',String(selected))})});$('.add-to-cart').onclick=()=>{if(!selectedSize){showToast('Выберете размер');return}const entry=cartEntry(p.id);if(entry)entry.size=selectedSize;else state.cart.push({id:p.id,size:selectedSize});renderProducts();renderCart();close()};open('detail')}
function toggleCart(id){state.cart=state.cart.filter(x=>x.id!==id);renderProducts();renderCart()}
function renderCart(){const items=state.cart.map(x=>({...products.find(p=>p.id===x.id),size:x.size})).filter(p=>p.id),holder=$('.cart-items');holder.innerHTML='';$('.cart-count').textContent=items.length||'';$('.cart-total-count').textContent=items.length?'· '+items.length:'';$('.cart-empty').hidden=items.length>0;$('.cart-footer').style.display=items.length?'grid':'none';items.forEach(p=>{const row=document.createElement('div');row.className='cart-item';row.innerHTML=`<img class="cart-thumb" src="${p.image}" alt=""><div><h3>${p.name}</h3><p>${p.type} · размер ${p.size}</p><strong>${rub(p.price)}</strong></div><button class="remove" aria-label="Убрать ${p.name}">×</button>`;row.querySelector('.remove').onclick=()=>toggleCart(p.id);holder.append(row)});$('.cart-total').textContent=rub(items.reduce((s,p)=>s+p.price,0))}
function close(){$$('.sheet').forEach(x=>{x.classList.remove('open');x.setAttribute('aria-hidden','true')});$('.scrim').hidden=true}function open(which){close();const el=$('.'+which);el.classList.add('open');el.setAttribute('aria-hidden','false');$('.scrim').hidden=false}
$('.filter-open').onclick=()=>open('filters');$('.cart-trigger').onclick=()=>open('cart');$$('.close-sheet').forEach(b=>b.onclick=close);$('.scrim').onclick=close;const formatPrice=n=>new Intl.NumberFormat('ru-RU').format(n);$('#min-price-range').oninput=e=>{state.min=+e.target.value;if(state.min>state.max){state.max=state.min;$('#max-price-range').value=state.max}$('#max-price-range').min=state.min;$('#min-price').textContent=formatPrice(state.min);$('#max-price').textContent=formatPrice(state.max)};$('#max-price-range').oninput=e=>{state.max=+e.target.value;if(state.max<state.min){state.min=state.max;$('#min-price-range').value=state.min}$('#min-price-range').max=state.max;$('#min-price').textContent=formatPrice(state.min);$('#max-price').textContent=formatPrice(state.max)};$$('.size-options button').forEach(b=>b.onclick=()=>{b.classList.toggle('selected');$$('.size-options button').forEach(x=>{if(x!==b)x.classList.remove('selected')});state.size=b.classList.contains('selected')?b.textContent:null});$('.apply').onclick=()=>{state.color=$('#color').value;renderProducts();close()};$('.reset').onclick=()=>{state.min=35000;state.max=95000;state.color='all';state.size=null;$('#min-price-range').value=35000;$('#max-price-range').value=95000;$('#min-price-range').max=95000;$('#max-price-range').min=35000;$('#min-price').textContent='35 000';$('#max-price').textContent='95 000';$('#color').value='all';$$('.size-options button').forEach(x=>x.classList.remove('selected'))};$('.consult').onclick=()=>location.href='booking.html?d='+state.cart.map(x=>x.id+':'+x.size).join(',');renderProducts();renderCart();
